import{_ as a,o as r,c as e,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const c=JSON.parse('{"title":"Is Your Driving World Model an All-Around Player?","description":"","frontmatter":{"title":"Is Your Driving World Model an All-Around Player?","arxiv":"2605.10858","date":"2026-05-11","authors":"Lingdong Kong, Ao Liang, Tianyi Yan, Hongsi Liu, Yu Yang, Ziqi Huang, Xian Sun, Wei Yin, Jialong Zuo, Yixuan Hu, Dekai Zhu, Dongyue Lu, Youquan Liu, Guangfeng Jiang, Linfeng Li, Xiangtai Li, Long Zhuo, Lai Xing Ng, Benoit R. Cottereau, Changxin Gao, Liang Pan, Wei Tsang Ooi, Ziwei Liu","categories":"cs.CV, cs.RO","topics":"世界模型, 驾驶评测基准, 闭环仿真","outline":[2,2]},"headers":[],"relativePath":"papers/2605.10858.md","filePath":"papers/2605.10858.md","lastUpdated":null}'),o={name:"papers/2605.10858.md"};function i(s,n,l,g,p,d){return r(),e("div",null,[...n[0]||(n[0]=[t('<h1 id="is-your-driving-world-model-an-all-around-player" tabindex="-1">Is Your Driving World Model an All-Around Player? <a class="header-anchor" href="#is-your-driving-world-model-an-all-around-player" aria-label="Permalink to &quot;Is Your Driving World Model an All-Around Player?&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2605.10858" target="_blank" rel="noreferrer">2605.10858</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-05-11</td></tr><tr><td><strong>作者</strong></td><td>Lingdong Kong, Ao Liang, Tianyi Yan, Hongsi Liu, Yu Yang, Ziqi Huang, Xian Sun, Wei Yin, Jialong Zuo, Yixuan Hu, Dekai Zhu, Dongyue Lu, Youquan Liu, Guangfeng Jiang, Linfeng Li, Xiangtai Li, Long Zhuo, Lai Xing Ng, Benoit R. Cottereau, Changxin Gao, Liang Pan, Wei Tsang Ooi, Ziwei Liu（NUS / NTU / USTC / ZJU 等）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV, cs.RO（CVPR 2026 VideoWorldModel Workshop）</td></tr><tr><td><strong>一句话</strong></td><td>提出 WorldLens：把驾驶世界模型的评测从「看着真不真」扩展到生成 / 4D 重建 / 动作跟随 / 下游任务 / 人类偏好五个维度共 24 项指标，并配套 26,808 条人工打分与一个蒸馏出来的 VLM 评测 agent。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/world-models">世界模型</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>一个具体的失败场景：某个 SOTA 驾驶世界模型生成的多视角视频纹理锐利、光照自然、运动流畅，但把一个预训练 planner 放进这个生成世界里执行常规机动，几秒内就撞车或冲出路面。论文报告的数字是，即便表现最好的世界模型，闭环控制下的路线完成率也<strong>不到 14%</strong>。</p><p>这个反差指向一个评测缺口：领域普遍用 FID、FVD、LPIPS 打分，而这些指标是为<strong>图像质量</strong>设计的，不是为<strong>世界保真度</strong>设计的。它们能量化感知相似度，却完全无法说明底层几何是否连贯、物理是否合理、生成世界能否支撑下游自动驾驶任务。后果是整个领域在优化一个不完整的目标：<strong>看起来像真的、但行为不像真的世界</strong>。缺少统一评测协议还带来第二个问题——某一轴（纹理真实感）上的进步会掩盖另一轴（3D 一致性、动作可控性）上的退步，使模型之间无法比较，真正的瓶颈也识别不出来。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>生成侧</strong>已经很强：MagicDrive、DreamForge、DriveDreamer-2、OpenDWM、DiST-4D、X-Scene 这一批工作能产出越来越难与真实行车记录仪区分的多视角序列。<strong>评测侧</strong>则明显滞后。VBench 一类视频生成基准衡量的是通用视频质量维度，不覆盖驾驶特有的几何与行为约束；FID/FVD/LPIPS 是分布或感知相似度，对「这个世界能不能被规划器安全使用」完全沉默。</p><p>为什么这些指标当年没被替换？论文给出的解释链条是合理的：像素级指标便宜、可复现、跨论文可比；而几何与行为保真度的测量需要额外的重建管线、预训练 planner 与闭环仿真环境，成本高且难标准化。真正缺的不是「有人想到过要测几何」，而是<strong>没有把这些异质测量统一进一个可复现协议</strong>。此外，人类感知这一层此前只有零散的 user study，缺少规模化、带理由的标注数据，因此也无法训练自动评测器。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>站在 2026 年初的位置，已有三条独立的技术线：（1）4D Gaussian Splatting 能把视频序列抬成显式 3D 表示并从新视角重渲染；（2）NAVSIM / DriveArena 一类工作已经把开环 PDMS 与闭环 Arena Driving Score 标准化；（3）BEVFusion、SparseOcc 一类感知模型可以直接吃合成数据做训练与评估。</p><p>一个认真研究者的推理会是：既然「世界模型好不好」难以直接定义，那就<strong>用它的下游用途反过来定义</strong>。视频能被重建成干净的 4D 高斯场吗？重渲染出的侧移视角有没有 floater？预训练 planner 在里面能不能开完一条路线？合成数据能不能训出可用的检测器？最后，人看着觉得真吗？这五问各自都有现成工具，把它们拼成一个矩阵，天然就得到一个多轴基准。至于人类偏好这一轴，标注不可规模化——但如果标注里同时含<strong>数值分与文字理由</strong>，就正好是训练一个 VLM 评测器的监督信号。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>外观、几何、行为在当前架构里是三个<strong>几乎独立</strong>的目标，所以单轴指标必然掩盖 trade-off。要暴露它，就得让同一个模型同时穿过五面「透镜」：像素、4D 重建、闭环规划、下游感知、人类判断。一旦并排看，「纹理最好的模型下游检测掉 30–50%」这类事实就再也藏不住了。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 OpenDWM 生成的一段 nuScenes 场景视频为例，WorldLens 的处理路径是：</p><ul><li><strong>Generation（8 维）</strong>：裁出物体送 class-specific 分类器算 Subject Fidelity（G.1）；用 ReID 与 DINO 特征跟踪跨帧身份稳定性得 Subject Coherence / Consistency（G.2/G.3）；用深度估计算帧间深度平滑性 Depth Discrepancy（G.4）；在 CLIP 与 SegFormer 空间里算 Temporal / Semantic Consistency（G.5/G.6）；I3D 特征上算 Perceptual Discrepancy（G.7）与多相机 Cross-View Consistency（G.8）。</li><li><strong>Reconstruction（4 维）</strong>：把整段序列抬成 4D Gaussian 场，在训练位姿下重渲染算 Photometric Error（R.1，LPIPS/PSNR/SSIM），用 Grounded-SAM 2 做深度比对算 Geometric Discrepancy（R.2），再在未见视角下算 Novel-View Quality / Discrepancy（R.3/R.4）。这一步是几何连贯性的<strong>判定性测试</strong>。</li><li><strong>Action-Following（4 维）</strong>：Displacement Error（A.1）、开环 PDMS（A.2）、闭环 Route Completion（A.3）、闭环 Arena Driving Score（A.4）。</li><li><strong>Downstream Task（4 维）</strong>：用生成视频跑 BEVFusion 地图分割（D.1）、3D 检测 NDS（D.2）、3D 跟踪 AMOTA（D.3）、SparseOcc RayIoU 占据预测（D.4）。</li><li><strong>Human Preference（4 维）</strong>：10 名标注者分两组、1–10 分评 World Realism、Physical Plausibility、3D &amp; 4D Consistency、Behavioral Safety。每条标注同时看生成视频、语义分割、深度图、3D 框叠加四路对齐模态，平均耗时约 128 秒，总计超过 <strong>930 小时</strong>，两组分歧的样本重评。</li></ul><p>标注沉淀为 <strong>WorldLens-26K</strong>（26,808 条「分数 + 文字理由」记录），再以 LoRA SFT 在 Qwen3-VL-8B 上蒸馏出 <strong>WorldLens-Agent</strong>，它同时输出各维度分数与模仿人类推理的解释，并在训练时未见过的 Gen3C 视频上做零样本评测，评分与人工标注高度吻合。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>评测对象是六个代表性模型：MagicDrive、DreamForge、DriveDreamer-2、OpenDWM、DiST-4D、X-Scene。论文围绕五个核心发现组织结果：</p><p><strong>没有全能选手。</strong> OpenDWM 靠多数据集训练在 subject fidelity 与 coherence 上领先；DiST-4D 在 perceptual discrepancy、cross-view consistency 与全部重建指标上占优；DriveDreamer-2 语义一致性与几何差异最好但物体级真实感落后。所有模型都显著低于 Empirical Max。</p><p><strong>感知质量 ≠ 功能可用性。</strong> 这是最有分量的一条。OpenDWM 拿到最好的 subject fidelity（36.30）与最低重建光度误差（0.065 LPIPS），但 3D 检测只有 21.96%、跟踪只有 6.90%，比 DiST-4D 低约 30–50%；DiST-4D 用几何感知的 RGB-D 生成牺牲一点视觉保真，换来 35.55% 地图分割、33.22% 检测、15.30% 跟踪。</p><p><strong>2D 保真不保证 4D 连贯。</strong> 抬成 4D 高斯场再从侧移视角重渲染时，MagicDrive 产生密集 floater，光度误差是 OpenDWM 的两倍以上；只有 DiST-4D 在横向相机偏移下保持干净几何，其解耦时空扩散加显式深度监督把光度与几何误差各砍约 55%。</p><p><strong>开环成绩掩盖闭环失败。</strong> 所有模型开环 PDMS 都在 71%–79% 这个「看起来还行」的区间，但闭环路线完成率骤降到 <strong>6%–14%</strong>，最好的 RLGF 也只有 13.51%，失败模式是频繁碰撞与偏离路面。</p><p><strong>人类感知与几何一致性相关。</strong> 四个感知维度上人类平均分只有 2–3 / 10；几何一致性强的模型（DiST-4D）拿到更高的真实感与物理合理性评分，视觉讨喜但几何不稳的模型（MagicDrive）最低。</p><p>论文由此给出四条设计原则：把几何当一等训练目标；外观与结构联合优化；必须做闭环评测；必须做多轴评测。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：当前驾驶世界模型的评测只测「像不像真的」，不测「行为是否真实」。WorldLens 用五个维度 24 项指标把评测扩到 4D 重建、闭环规划、下游感知与人类判断。六个代表模型没有一个全轴领先，纹理最好的模型下游检测反而掉 30–50%。开环 PDMS 71–79% 的模型闭环路线完成率只有 6–14%，人类真实感评分仅 2–3 分（满分 10）。26,808 条带理由的人工标注被蒸馏成一个 VLM 评测 agent，使可解释的自动评测得以规模化。</p><p><strong>3 句话版</strong>：领域一直在优化外观而非行为保真度。WorldLens 用 24 项指标同时照出外观、几何、行为、下游可用性与人类感知，暴露出模型之间尖锐的 trade-off。最刺眼的证据是开环表现体面的模型在闭环里几乎开不完任何一条路线。</p><p><strong>1 句话版</strong>：把驾驶世界模型放进五面透镜下看，没有一个是全能选手，而且开环好看的闭环基本不能用。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最要害的假设是：<strong>闭环路线完成率 6–14% 主要归因于世界模型的因果与物理不一致，而非那个固定 planner 与生成图像之间的 domain gap。</strong> 「感知质量 ≠ 功能可用性」这条核心结论几乎完全压在这个归因上。</p><p>它在实践中很可能不成立：planner 是在真实图像上预训练的，生成视频即使几何完美，其纹理统计、噪声特性、色彩响应仍与真实传感器数据不同；闭环里 planner 的每一步误差还会反过来改变世界模型的条件输入，两侧的分布漂移互相放大。论文给出的间接证据是开环 PDMS 有 71–79%，说明 planner 至少能从孤立帧里读出有效线索——这削弱但没有排除 domain gap 解释，因为开环不涉及误差累积。<strong>缺的证据是一个对照组</strong>：同一个 planner 在真实回放视频或图形学仿真器里闭环跑同样路线的完成率上界。工作坊版本正文里我没有看到这个对照（完整版论文另见 Liang et al., CVPR 2026，未经核验）。若真实视频上的完成率也只有 20–30%，那 6–14% 的解读就要大幅改写。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>一周可做、且不需要复现整套 24 维基准的方案：</p><ol><li>取两个公开权重的驾驶世界模型（例如 OpenDWM 与 DiST-4D），在 nuScenes val 上各生成 50 段序列。</li><li>只复现 <strong>Downstream Task</strong> 这一轴：用一个现成的 3D 检测器分别在真实视频与两组生成视频上评估 NDS。</li><li>同时用现成的单目深度模型算帧间深度平滑性作为几何代理指标。</li><li><strong>支持假设的结果</strong>：OpenDWM 的 NDS 相对 DiST-4D 低 30% 量级，且其几何代理指标同时更差——说明「外观强、几何弱、下游差」这条链条稳健。</li><li><strong>反驳假设的结果</strong>：两者 NDS 差距在 5% 以内，或者差距方向与几何代理指标不一致——说明原结论对检测器选择或评测切分敏感。</li></ol><p>这个实验只需要推理与评估，不需要训练，也不需要 4D 重建与闭环仿真环境。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>站在反对者立场，最有力的攻击是<strong>给闭环失败提供替代解释</strong>：设计一个 planner 适配实验。取评测中最强的世界模型，用它生成的视频对 planner 做轻量微调（或仅做输入端的风格对齐 / 特征归一化），再重跑闭环路线完成率。</p><ul><li>如果完成率从 13.5% 跳到 40% 以上，那么「生成世界缺乏维持自动驾驶所需的因果与物理一致性」这个诊断就被替换成「评测协议缺少 planner 适配」，四条设计原则里的第三条（必须闭环评测）仍然成立，但第一、二条（几何是一等目标）的证据力显著削弱。</li><li>第二个攻击面是<strong>可预测的失败条件</strong>：24 维指标的聚合可能对模型的原生分辨率、训练数据规模与视角数敏感。让同一个架构在两个数据规模下训练，如果「no all-rounder」的雷达图形状随数据量单调变化，那么「当前架构把外观、几何、动力学当作独立目标」这个架构层面的论断，就会被降格为一个数据规模层面的观察。</li></ul><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>(a) 驱动局限</strong>：WorldLens 仍然把世界模型当作被打分的<strong>对象</strong>——每个维度输出一个标量，然后人为聚合。但世界模型的实际用途是<strong>替代真实路测做决策</strong>：选哪个 planner、哪个版本能上车。一个在所有维度上都得高分的模拟器，如果把两个 planner 的优劣排反了，对工程决策就是有害的。</p><p><strong>(b) 可借鉴的相邻领域工具</strong>：off-policy evaluation 与因果推断里的「决策一致性」框架。把基准的目标函数从「生成世界与真实世界有多像」改成「<strong>在生成世界里做出的排序，与在真实世界里做出的排序有多一致</strong>」，即 policy ranking fidelity。可以直接借用 OPE 的 regret bound 与 rank correlation（Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>）工具，把世界模型的价值表述为一个决策后悔上界而非相似度分数。</p><p><strong>(c) 第一个实验</strong>：取 5 个能力已知有差异的 planner，在每个候选世界模型里跑闭环拿 Arena Driving Score 排序，再与它们在真实日志回放基准上的排序比 Kendall&#39;s <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.1132em;">τ</span></span></span></span>。此时会出现一个 WorldLens 现有框架无法表达的现象——某个视觉质量平庸但<strong>误差方向无偏</strong>的世界模型，可能拿到最高的排序一致性。如果这个现象成立，它直接反驳「先把画面做真，功能自然会好」的隐含前提，并给出一个可优化的新目标：不是最小化与真实的距离，而是最小化<strong>排序反转率</strong>。</p>',46)])])}const h=a(o,[["render",i]]);export{c as __pageData,h as default};
